// Persistent virtual-estimator state (context survives across ticks; msg does not).
// Instead of independent random draws each second, we random-walk a single
// "load" scalar (0-1, how hard the pump is working) with mean reversion, plus
// occasional FAULT/STOPPED episodes. All 6 metrics are derived FROM load
// (+ a fault-severity ramp), so they move together the way real pump
// telemetry does, instead of jumping to unrelated random numbers every tick.

function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function jitter(scale) { return (Math.random() - 0.5) * 2 * scale; }
function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function step(current, target, speed, noise) { return current + speed * (target - current) + jitter(noise); }

let state = context.get('state');
if (!state) {
    state = { load: 0.5, regime: 'RUNNING', regimeTicksLeft: 0, regimeTotalTicks: 0, faultSeverity: 0 };
}

// Regime transitions: mostly RUNNING, with rare FAULT / STOPPED episodes.
if (state.regimeTicksLeft > 0) {
    state.regimeTicksLeft--;
    if (state.regimeTicksLeft === 0) {
        state.regime = 'RUNNING';
        state.faultSeverity = 0;
    }
} else if (state.regime === 'RUNNING') {
    if (Math.random() < 0.003) {
        state.regime = 'FAULT';
        state.regimeTotalTicks = randInt(15, 40);
        state.regimeTicksLeft = state.regimeTotalTicks;
    } else if (Math.random() < 0.002) {
        state.regime = 'STOPPED';
        state.regimeTotalTicks = randInt(20, 60);
        state.regimeTicksLeft = state.regimeTotalTicks;
    }
}

// Fault severity ramps 0 -> ~1 across the episode, then resets on recovery.
if (state.regime === 'FAULT') {
    state.faultSeverity = 1 - (state.regimeTicksLeft / state.regimeTotalTicks);
}

// "load" = how hard the pump is working (0-1). Random-walks with mean
// reversion toward a regime-specific target, so it drifts smoothly instead
// of teleporting -- this is what gives every metric real momentum/trend.
const loadTarget = state.regime === 'STOPPED' ? 0.02 : 0.5;
const loadSpeed  = state.regime === 'STOPPED' ? 0.35 : 0.06;
const loadNoise  = state.regime === 'STOPPED' ? 0.02 : 0.05;
state.load = clamp(step(state.load, loadTarget, loadSpeed, loadNoise), 0.02, 1);

// Noise gets louder as fault severity rises (heteroscedastic measurement noise).
const noiseScale = 1 + state.faultSeverity * 2;
const load = state.load;
const fault = state.faultSeverity;

function round1(v) { return Math.round(v * 10) / 10; }

msg.payload = {
    flowRate:          round1(clamp(50   + load * 250 - fault * 80  + jitter(6    * noiseScale), 50,   300)),
    rpm:               round1(clamp(1000 + load * 2600              + jitter(30   * noiseScale), 1000, 3600)),
    vibration:         round1(clamp(0.5  + load * 4   + fault * 6   + jitter(0.4  * noiseScale), 0.5,  12)),
    suctionPressure:   round1(clamp(3    - load * 2.5 + fault * 0.3 + jitter(0.08 * noiseScale), 0.5,  3)),
    dischargePressure: round1(clamp(2    + load * 10  - fault * 3   + jitter(0.3  * noiseScale), 2,    12)),
    motorTemp:         round1(clamp(20   + load * 40  + fault * 25  + jitter(1.5  * noiseScale), 20,   90)),
    status:            state.regime,
    timestamp:         new Date().toISOString()
};

context.set('state', state);

// Tell the backend the body is JSON so Express parses it correctly.
msg.headers = { "Content-Type": "application/json" };

return msg;

// preprocess_minute — Stage 1 (physics-informed validation) runs on every
// tick; Stages 2-8 (buffering, missing-data detection, outlier handling,
// aggregation, quality scoring) run once every 60 ticks (~1 minute).
//
// Output 0: the raw reading (annotated with validation flags), sent EVERY
//           tick -> POST /api/data -> raw_telemetry (the untouched audit trail
//           still gets every second; only the annotation fields are added).
// Output 1: the one-minute aggregate, sent only every 60th tick
//           -> POST /api/processed -> processed_telemetry.

const METRICS = ['flowRate', 'rpm', 'vibration', 'suctionPressure', 'dischargePressure', 'motorTemp'];

// Mirrors server/utils/validation.js RANGES (the Express boundary's hard
// reject-if-impossible gate). Same bounds deliberately: a reading that would
// fail there is exactly what should be FLAGGED here. This stage never
// rejects a reading -- it only annotates it, so raw_telemetry keeps a
// complete, unbroken audit trail even for values that later prove suspect.
const RANGES = {
    flowRate: [0, 500], rpm: [0, 5000], vibration: [0, 25],
    suctionPressure: [0, 10], dischargePressure: [0, 25], motorTemp: [-20, 150]
};

function validatePhysics(sample) {
    const violations = [];
    for (const metric of METRICS) {
        const range = RANGES[metric];
        if (sample[metric] < range[0] || sample[metric] > range[1]) {
            violations.push(metric + ' out of range');
        }
    }
    // Cross-variable rule: a centrifugal pump always adds head, so discharge
    // pressure must exceed suction pressure while running.
    if (sample.dischargePressure <= sample.suctionPressure) {
        violations.push('dischargePressure must exceed suctionPressure');
    }
    // Status/measurement consistency: a STOPPED pump should show ~zero flow/rpm.
    if (sample.status === 'STOPPED' && (sample.flowRate > 20 || sample.rpm > 200)) {
        violations.push('STOPPED status but flow/rpm indicate the pump is running');
    }
    return violations;
}

function round2(v) { return Math.round(v * 100) / 100; }

// ---- Stage 1: physics-informed validation (every tick) ----
const violations = validatePhysics(msg.payload);
const annotated = Object.assign({}, msg.payload, {
    isSynthetic: true,
    physicsValid: violations.length === 0,
    physicsViolations: violations.length ? violations : null
});

const rawMsg = { payload: annotated, headers: { 'Content-Type': 'application/json' } };

// ---- Stage 2: buffer this tick (node-scoped context persists across ticks) ----
let buffer = context.get('buffer') || [];
buffer.push(annotated);
context.set('buffer', buffer);

if (buffer.length < 60) {
    return [rawMsg, null]; // not yet a full window -> no processed output this tick
}

context.set('buffer', []); // reset for the next window

// ---- Stage 3: missing-sample detection (gaps in the ~1 Hz timestamp series) ----
let missingCount = 0;
for (let i = 1; i < buffer.length; i++) {
    const dtSec = (new Date(buffer[i].timestamp).getTime() - new Date(buffer[i - 1].timestamp).getTime()) / 1000;
    if (dtSec > 1.5) missingCount += Math.round(dtSec) - 1;
}

// ---- Stage 4: outlier detection -- Hampel filter (median + MAD), CAP not delete ----
// Capping (not deleting) preserves sample count; the true raw value is still
// in raw_telemetry regardless, so nothing is ever lost, only the AGGREGATE
// is protected from a single spurious spike.
function hampelCap(values, k) {
    const sorted = values.slice().sort(function (a, b) { return a - b; });
    const median = sorted[Math.floor(sorted.length / 2)];
    const absDev = values.map(function (v) { return Math.abs(v - median); });
    const madSorted = absDev.slice().sort(function (a, b) { return a - b; });
    const mad = 1.4826 * madSorted[Math.floor(madSorted.length / 2)];
    let outliers = 0;
    const capped = values.map(function (v) {
        if (mad > 0 && Math.abs(v - median) > k * mad) {
            outliers++;
            return median;
        }
        return v;
    });
    return { capped: capped, outliers: outliers };
}

const stats = {};
let outlierCount = 0;

for (const metric of METRICS) {
    const raw = buffer.map(function (s) { return s[metric]; });
    const result = hampelCap(raw, 3);
    outlierCount += result.outliers;

    const capped = result.capped;
    const n = capped.length;
    const meanVal = capped.reduce(function (a, b) { return a + b; }, 0) / n;
    const sortedCapped = capped.slice().sort(function (a, b) { return a - b; });
    const medianVal = sortedCapped[Math.floor(n / 2)];
    const variance = capped.reduce(function (a, b) { return a + Math.pow(b - meanVal, 2); }, 0) / n;

    stats[metric] = {
        Mean: round2(meanVal),
        Median: round2(medianVal),
        Min: Math.min.apply(null, capped),
        Max: Math.max.apply(null, capped),
        StdDev: round2(Math.sqrt(variance)),
        Last: raw[raw.length - 1] // true (uncapped) end-of-window value -- the real instantaneous state
    };
}

// ---- Stage 5 (status/regime duration, feeds aggregation) ----
const statusCounts = { RUNNING: 0, FAULT: 0, STOPPED: 0 };
for (const s of buffer) statusCounts[s.status] = (statusCounts[s.status] || 0) + 1;
const dominantStatus = Object.keys(statusCounts).sort(function (a, b) { return statusCounts[b] - statusCounts[a]; })[0];

// ---- Stage 7/8: data quality assessment + metadata ----
const n = buffer.length;
const physicsViolationCount = buffer.filter(function (s) { return s.physicsValid === false; }).length;
const missingRate = missingCount / (n + missingCount);
const outlierRate = outlierCount / (n * METRICS.length);
const physicsPassRate = 1 - (physicsViolationCount / n);

// Weighted quality score (0-100): missing data hurts most (a gap can't be
// recovered), outliers are already contained by capping (lower weight),
// physics violations matter but are advisory (a FAULT episode can look
// "physically odd" without being a data-quality problem).
const qualityScore = round2(100 * (
    0.4 * (1 - missingRate) +
    0.3 * (1 - outlierRate) +
    0.3 * physicsPassRate
));
const qualityLabel = qualityScore >= 90 ? 'GOOD' : (qualityScore >= 70 ? 'FAIR' : 'POOR');

const windowStart = buffer[0].timestamp;
const windowEnd = buffer[buffer.length - 1].timestamp;

const processedPayload = {
    windowStart: windowStart,
    windowEnd: windowEnd,
    timestamp: windowEnd, // canonical timestamp = end of window, see design doc
    dominantStatus: dominantStatus,
    runningSeconds: statusCounts.RUNNING,
    faultSeconds: statusCounts.FAULT,
    stoppedSeconds: statusCounts.STOPPED,
    sampleCount: n,
    expectedSampleCount: 60,
    missingSampleCount: missingCount,
    imputedSampleCount: missingCount,
    outlierCount: outlierCount,
    physicsViolationCount: physicsViolationCount,
    missingRate: round2(missingRate),
    imputationRate: round2(missingRate),
    outlierRate: round2(outlierRate),
    physicsPassRate: round2(physicsPassRate),
    qualityScore: qualityScore,
    qualityLabel: qualityLabel,
    isImputed: missingCount > 0,
    preprocessingVersion: 'v1',
    preprocessingTimestamp: new Date().toISOString()
};

for (const metric of METRICS) {
    processedPayload[metric + 'Mean'] = stats[metric].Mean;
    processedPayload[metric + 'Median'] = stats[metric].Median;
    processedPayload[metric + 'Min'] = stats[metric].Min;
    processedPayload[metric + 'Max'] = stats[metric].Max;
    processedPayload[metric + 'StdDev'] = stats[metric].StdDev;
    processedPayload[metric + 'Last'] = stats[metric].Last;
}

const processedMsg = { payload: processedPayload, headers: { 'Content-Type': 'application/json' } };

return [rawMsg, processedMsg];
